import java.util.*;

public class MinCostMaxFlow {
    static class Edge {
        int to, capacity, cost, rev;
        Edge(int to, int capacity, int cost, int rev) {
            this.to = to;
            this.capacity = capacity;
            this.cost = cost;
            this.rev = rev;
        }
    }

    static class FlowNetwork {
        static final int MAXN = 5010;
        List<Edge>[] G = new ArrayList[MAXN];
        int V;
        int[] h = new int[MAXN], dist = new int[MAXN], prevv = new int[MAXN], preve = new int[MAXN];

        FlowNetwork() {
            for (int i = 0; i < MAXN; i++) {
                G[i] = new ArrayList<>();
            }
        }

        void init(int n) {
            V = n;
            for (int i = 0; i < V; i++) {
                G[i].clear();
            }
        }

        void addEdge(int from, int to, int cap, int cost) {
            G[from].add(new Edge(to, cap, cost, G[to].size()));
            G[to].add(new Edge(from, 0, -cost, G[from].size() - 1));
        }

        int minCostFlow(int s, int t, int f) {
            int res = 0;
            Arrays.fill(h, 0);
            while (f > 0) {
                PriorityQueue<int[]> que = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
                Arrays.fill(dist, Integer.MAX_VALUE);
                dist[s] = 0;
                que.offer(new int[]{0, s});
                while (!que.isEmpty()) {
                    int[] p = que.poll();
                    int d = p[0], v = p[1];
                    if (dist[v] < d) continue;
                    for (int i = 0; i < G[v].size(); i++) {
                        Edge e = G[v].get(i);
                        if (e.capacity > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]) {
                            dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                            prevv[e.to] = v;
                            preve[e.to] = i;
                            que.offer(new int[]{dist[e.to], e.to});
                        }
                    }
                }
                if (dist[t] == Integer.MAX_VALUE) return -1;
                for (int v = 0; v < V; v++) h[v] += dist[v];
                int d = f;
                for (int v = t; v != s; v = prevv[v]) {
                    d = Math.min(d, G[prevv[v]].get(preve[v]).capacity);
                }
                f -= d;
                res += d * h[t];
                for (int v = t; v != s; v = prevv[v]) {
                    Edge e = G[prevv[v]].get(preve[v]);
                    e.capacity -= d;
                    G[v].get(e.rev).capacity += d;
                }
            }
            return res;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        int[] a = new int[50];
        int[] cnt = new int[50];
        for (int i = 0; i < k; i++) {
            a[i] = sc.nextInt();
            cnt[a[i] - 1]++;
        }

        List<Integer>[] e = new ArrayList[50];
        for (int i = 0; i < 50; i++) {
            e[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            x--;
            y--;
            e[x].add(y);
            e[y].add(x);
        }

        int totalNodes = n * 100 + 2;
        FlowNetwork flow = new FlowNetwork();
        flow.init(totalNodes);

        for (int i = 0; i < n; i++) {
            flow.addEdge(n * 100, i, cnt[i], 0);
        }

        for (int i = 0; i < 100; i++) {
            flow.addEdge(i * n, n * 100 + 1, k, c * i);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 99; j++) {
                flow.addEdge(j * n + i, (j + 1) * n + i, k, 0);
            }
            for (int to : e[i]) {
                for (int j = 0; j < 99; j++) {
                    for (int u = 0; u < k; u++) {
                        int cost = (u + 1) * (u + 1) * d - u * u * d;
                        flow.addEdge(j * n + i, (j + 1) * n + to, 1, cost);
                    }
                }
            }
        }

        System.out.println(flow.minCostFlow(n * 100, n * 100 + 1, k));
        sc.close();
    }
}

